def is_woodall(x):
    if x == 1:
        return True
    if x % 2 == 0:
        return False

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Factor out powers of 2
    power_of_2 = 0
    temp = x
    while temp % 2 == 0:
        temp = temp // 2
        power_of_2 += 1

    # Check if remaining part is Mersenne prime (2^p - 1)
    mersenne = temp + 1
    p = mersenne.bit_length() - 1

    if not is_prime(p):
        return False

    if not is_prime(mersenne):
        return False

    return p == power_of_2

